---level24 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl24_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		sound.play("53-1")		if dialog.show("Level24-1", faceZhoumei) ==1 then break end		sound.play("42-1")		if dialog.show("Level24-2", faceJingya) ==1 then break end		if dialog.show("Level24-3", faceRenzhen) ==1 then break end				--set story viewed flag        global.setBool("lvl24_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false	until trueendif isSkip then	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end